package pl.atrop.powerguard.bcknd.meter.infrastructure.rest; import java.math.BigDecimal; import pl.atrop.powerguard.bcknd.meter.domain.MeterConfiguration; public record MeterView(Integer id,Long sitePk,String clientId,String clientName,String siteId,String siteName,String edgeId,String uniqueKey,String name,BigDecimal instantaneousAlarmOnKw,BigDecimal instantaneousAlarmOffKw,BigDecimal quarterHourAlarmOnKw,BigDecimal quarterHourAlarmOffKw,boolean enabled,int displayOrder){public static MeterView from(MeterConfiguration m){return new MeterView(m.id(),m.sitePk(),m.clientId(),m.clientName(),m.siteId(),m.siteName(),m.edgeId(),m.uniqueKey(),m.name(),m.instantaneousAlarmOnKw(),m.instantaneousAlarmOffKw(),m.quarterHourAlarmOnKw(),m.quarterHourAlarmOffKw(),m.enabled(),m.displayOrder());}}
